class Solution {
  public long maxScore(int n, int[][] edges) {
    long[] arr = new long[n];
    int rightCount = n / 2, leftCount = (n - 1) / 2;
    // sequence: left values (n-2, n-4, ...) reversed, then n, then right values (n-1, n-3, ...)
    int pos = leftCount;
    arr[pos] = n;
    for (int i = 1, v = n - 1; i <= rightCount; i++, v -= 2) arr[pos + i] = v;
    for (int i = 1, v = n - 2; i <= leftCount; i++, v -= 2) arr[pos - i] = v;
    long sum = 0;
    for (int i = 0; i + 1 < n; i++) sum += arr[i] * arr[i + 1];
    if (edges.length == n && n > 2) sum += arr[0] * arr[n - 1];
    return sum;
  }
}
